const items = $input.all();
const transactions = items.filter(i => i.json.transaction_id !== undefined).map(i => i.json);
const members = items.filter(i => i.json.member_name !== undefined).map(i => i.json);

const tierRank = { regular: 0, silver: 1, gold: 2, platinum: 3 };
function rank(tier) {
  if (!tier) return -1;
  const key = String(tier).trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(tierRank, key) ? tierRank[key] : -1;
}

const memberById = {};
members.forEach(m => { if (m.member_id) memberById[String(m.member_id).trim()] = m; });

const phoneGroups = {};
const emailGroups = {};
members.forEach(m => {
  if (m.phone_number) {
    const p = String(m.phone_number).trim();
    if (!phoneGroups[p]) phoneGroups[p] = [];
    phoneGroups[p].push(String(m.member_id).trim());
  }
  if (m.email) {
    const e = String(m.email).trim().toLowerCase();
    if (!emailGroups[e]) emailGroups[e] = [];
    emailGroups[e].push(String(m.member_id).trim());
  }
});
const duplicateEvidence = {};
Object.keys(phoneGroups).forEach(p => {
  const ids = phoneGroups[p];
  if (ids.length > 1) {
    ids.forEach(id => {
      const others = ids.filter(x => x !== id);
      duplicateEvidence[id] = (duplicateEvidence[id] || []).concat("nomor telepon sama dengan member " + others.join(", "));
    });
  }
});
Object.keys(emailGroups).forEach(e => {
  const ids = emailGroups[e];
  if (ids.length > 1) {
    ids.forEach(id => {
      const others = ids.filter(x => x !== id);
      duplicateEvidence[id] = (duplicateEvidence[id] || []).concat("email sama dengan member " + others.join(", "));
    });
  }
});

const cardGroups = {};
transactions.forEach(t => {
  const cardKey = t.card_key || ((t.card_last4 || "") + "|" + (t.issuing_bank || ""));
  if (!cardKey || cardKey === "|") return;
  if (!cardGroups[cardKey]) cardGroups[cardKey] = [];
  if (t.member_id && cardGroups[cardKey].indexOf(t.member_id) === -1) cardGroups[cardKey].push(t.member_id);
});

const byMember = {};
transactions.forEach(t => {
  if (!t.member_id) return;
  if (!byMember[t.member_id]) byMember[t.member_id] = [];
  byMember[t.member_id].push(t);
});
const travelEvidence = {};
const IMPOSSIBLE_TRAVEL_MINUTES = 90;
Object.keys(byMember).forEach(mid => {
  const list = byMember[mid].slice().sort((a, b) => new Date(a.transaction_datetime) - new Date(b.transaction_datetime));
  let i = 1;
  while (i < list.length) {
    const prev = list[i - 1];
    const curr = list[i];
    const prevCity = prev.store_city || prev.geo_area;
    const currCity = curr.store_city || curr.geo_area;
    const prevOnline = String(prev.channel || "").trim().toLowerCase() === "online" || String(prevCity || "").trim().toLowerCase() === "online";
    const currOnline = String(curr.channel || "").trim().toLowerCase() === "online" || String(currCity || "").trim().toLowerCase() === "online";
    if (!prevOnline && !currOnline && prevCity && currCity && prevCity !== currCity) {
      const diffMinutes = (new Date(curr.transaction_datetime) - new Date(prev.transaction_datetime)) / 60000;
      if (diffMinutes >= 0 && diffMinutes < IMPOSSIBLE_TRAVEL_MINUTES) {
        travelEvidence[curr.transaction_id] = prevCity + " pada " + prev.transaction_datetime + " lalu " + currCity + " pada " + curr.transaction_datetime + " (selisih " + Math.round(diffMinutes) + " menit)";
        travelEvidence[prev.transaction_id] = travelEvidence[curr.transaction_id];
      }
    }
    i = i + 1;
  }
});

const OPERATING_HOUR_START = 9;
const OPERATING_HOUR_END = 21;

const results = transactions.map(t => {
  const cardKey = t.card_key || ((t.card_last4 || "") + "|" + (t.issuing_bank || ""));
  const sharers = (cardGroups[cardKey] || []).filter(id => id !== t.member_id);
  const flag_R1 = sharers.length > 0;
  const evidence_R1 = flag_R1 ? ("Kartu yang sama juga dipakai oleh member " + sharers.join(", ")) : "Tidak ada indikasi kartu dipakai member lain pada batch ini";

  const memberTier = (t.member_id && memberById[String(t.member_id).trim()] && memberById[String(t.member_id).trim()].member_tier) || t.member_tier;
  const flag_R2 = rank(t.item_tier_requirement) > rank(memberTier);
  const evidence_R2 = flag_R2 ? ("Item membutuhkan tier " + t.item_tier_requirement + " namun member bertier " + memberTier) : "Tier item sesuai atau di bawah tier member";

  let hour = t.transaction_hour;
  if (hour === undefined || hour === null || hour === "") {
    const d = t.transaction_datetime ? new Date(t.transaction_datetime) : null;
    hour = d && !isNaN(d.getTime()) ? d.getHours() : null;
  }
  const flag_R3 = (hour !== null && hour !== undefined) ? (hour < OPERATING_HOUR_START || hour > OPERATING_HOUR_END) : false;
  const evidence_R3 = flag_R3 ? ("Transaksi pukul " + hour + ":00, di luar asumsi jam operasional " + OPERATING_HOUR_START + "-" + OPERATING_HOUR_END) : "Transaksi dalam rentang jam operasional yang diasumsikan";

  const tierKey = String(t.item_tier_requirement || "").trim().toLowerCase();
  const qty = Number(t.qty) || 0;
  let flag_R4 = false;
  let evidence_R4 = "Kuantitas dalam batas wajar";
  if (tierKey === "platinum" && qty > 1) { flag_R4 = true; evidence_R4 = "Item Platinum dibeli " + qty + " pcs, melebihi batas 1"; }
  if (tierKey === "gold" && qty > 2) { flag_R4 = true; evidence_R4 = "Item Gold dibeli " + qty + " pcs, melebihi batas 2"; }

  const flag_R5 = Boolean(travelEvidence[t.transaction_id]);
  const evidence_R5 = flag_R5 ? travelEvidence[t.transaction_id] : "Tidak ada transaksi lain dari member ini di kota berbeda dalam waktu singkat";

  const flag_R6 = Boolean(t.member_id && duplicateEvidence[String(t.member_id).trim()]);
  const evidence_R6 = flag_R6 ? duplicateEvidence[String(t.member_id).trim()].join("; ") : "Tidak ada kontak (telepon/email) yang sama dengan member lain";

  const anomaly_count = [flag_R1, flag_R2, flag_R3, flag_R4, flag_R5, flag_R6].filter(Boolean).length;

  const rest = {};
  Object.keys(t).forEach(key => { rest[key] = t[key]; });
  rest.flag_R1_card_sharing = flag_R1; rest.evidence_R1 = evidence_R1;
  rest.flag_R2_tier_mismatch = flag_R2; rest.evidence_R2 = evidence_R2;
  rest.flag_R3_outside_hours = flag_R3; rest.evidence_R3 = evidence_R3;
  rest.flag_R4_bulk_limited = flag_R4; rest.evidence_R4 = evidence_R4;
  rest.flag_R5_impossible_travel = flag_R5; rest.evidence_R5 = evidence_R5;
  rest.flag_R6_duplicate_account = flag_R6; rest.evidence_R6 = evidence_R6;
  rest.anomaly_count = anomaly_count;
  rest.is_anomaly = anomaly_count > 0;
  rest.is_anomaly_num = anomaly_count > 0 ? 1 : 0;
  rest.verified_at = new Date().toISOString();
  return { json: rest };
});

return results;

const original = $("Limit (Maks 3)").item.json;
const classified = $json.output;
const merged = Object.assign({}, original);
merged.priority = classified.priority;
merged.priority_rationale = classified.rationale;
return { json: merged };

const original = $("Gabungkan Prioritas").item.json;
const draft = $json.output;
const merged = Object.assign({}, original);
merged.alert_subject = draft.subject;
merged.alert_body_html = draft.body_html;
return { json: merged };
